const rawBody = $input.first().json.body || $input.first().json;

function normalize(body) {
  const contactId = body.contactId ?? body.contact_id ?? body.id ?? '';
  const name = body.contactName ?? body.full_name ?? body.name ?? '';
  const channelRaw = (body.channel ?? body.source ?? body.customData?.channel ?? '').toString().toLowerCase();
  let channel = 'unknown';
  if (channelRaw.includes('whatsapp')) channel = 'whatsapp';
  else if (channelRaw.includes('instagram') || channelRaw === 'ig') channel = 'instagram';
  else if (channelRaw.includes('messenger') || channelRaw.includes('facebook') || channelRaw.includes('fb')) channel = 'messenger';
  const message = body.message ?? body.lastMessage ?? body.message_body ?? body.body ?? '';
  const locationId = body.locationId ?? body.location_id ?? '';
  const attachmentUrl = body.attachmentUrl ?? body.attachment_url ?? body.mediaUrl ?? '';
  return { contactId, name, channel, message, locationId, attachmentUrl };
}

const current_body = normalize(rawBody);
const current_key = current_body.contactId;
const timestamp = new Date().toISOString();
const start_time = Date.now();

const result_body = { current_body, timestamp };

return [{
  key: current_key,
  body: JSON.stringify(result_body),
  timestamp,
  start_time
}];

function prepareForHttp(text) {
  if (text === null || text === undefined) return "";
  return String(text)
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\r\n/g, "\\n")
    .replace(/\n/g, "\\n")
    .replace(/\t/g, "\\t")
    .replace(/\*\*/g, "*")
    .trim();
}

const raw = $input.first().json.output || "";
const cleanRaw = raw.replace(/```(?:json)?\n?/g, '').trim();
const match = cleanRaw.match(/\{[\s\S]*\}/);

const entradaUsuarioActual = $('CONTEXT 1').first().json.entrada_usuario || null;

if (!match) {
  const recovered = prepareForHttp(cleanRaw);
  return [{ 
    json: { 
      respuesta: recovered || "Lo siento, tuve un problema procesando esa respuesta. ¿Puedes repetirlo?",
      accion_tipo: "error",
      error: "no_json",
      raw_output: raw,
      consulta_pendiente_guardar: entradaUsuarioActual,
      consulta_pendiente_limpiar: false
    }
  }];
}

try {
  const parsed = JSON.parse(match[0]);

  let respuesta = String(parsed.respuesta || "").trim();
  if (!respuesta) {
    const prefijo = cleanRaw.slice(0, match.index).trim();
    respuesta = prefijo || "Disculpa, tuve un problema generando la respuesta. ¿Puedes repetir tu mensaje?";
  }
  const accionTipo = parsed.accion?.tipo || "esperar";
  const transferir = parsed.escalar?.activar ? 1 : 0;
  const interesVehiculo = parsed.estado_lead?.interes_vehiculo || null;
  const metodoPago = parsed.estado_lead?.metodo_pago || null;
  const datosCompletos = !!(interesVehiculo && metodoPago);

  const respuestaFinal = prepareForHttp(respuesta);

  return [{
    json: {
      respuesta: respuestaFinal,
      accion_tipo: accionTipo,
      accion_razon: parsed.accion?.razon || "",
      proyecto: interesVehiculo,
      transferir: transferir,
      escalar_nivel: parsed.escalar?.nivel || null,
      escalar_motivo: parsed.escalar?.motivo || null,
      city: parsed.estado_lead?.city || null,
      interes_vehiculo: interesVehiculo,
      metodo_pago: metodoPago,
      timing_compra: parsed.estado_lead?.timing_compra || null,
      idioma_preferido: parsed.estado_lead?.idioma_preferido || null,
      resumen_ai: parsed.estado_lead?.resumen_ai || null,
      datos_completos: datosCompletos,
      intencion: parsed.metadatos?.intencion || null,
      idioma: parsed.metadatos?.idioma || null,
      confianza: parsed.metadatos?.confianza || null,
      herramientas_usadas: parsed.depuracion?.herramientas_usadas || [],
      ruta_decision: parsed.depuracion?.ruta_decision || "",
      advertencias: parsed.depuracion?.advertencias || [],
      raw: parsed,
      consulta_pendiente_guardar: parsed.consulta_pendiente?.guardar || null,
      consulta_pendiente_limpiar: parsed.consulta_pendiente?.limpiar || false,
      consulta_pendiente_retomar: parsed.consulta_pendiente?.retomar || null,
    }
  }];

} catch(e) {
  return [{ 
    json: { 
      respuesta: "Lo siento, tuve un problema procesando esa respuesta. ¿Puedes repetirlo?",
      accion_tipo: "error",
      error: "parse_failed",
      error_message: e.message,
      raw_output: raw,
      consulta_pendiente_guardar: entradaUsuarioActual,
      consulta_pendiente_limpiar: false
    }
  }];
}

